// Aborta o sync se a query nao trouxe linhas, para nunca truncar a tabela
// castor_src_sa1010 com uma base vazia por falha transitoria de conexao/query.
const rows = $input.all();
if (!rows.length) {
  throw new Error('SA1010 (live) retornou 0 linhas - sync abortado para nao truncar dados existentes.');
}
return rows;

// Mapeia colunas reais do Protheus (SA1010) para o schema de castor_src_sa1010.
// a1_codcli_raw = COD(6) + LOJA(2), igual ao layout do extrato em planilha.
// A1_MSBLQL confirmado no dicionario SX3 real (SA1;B5): 1=Inativo, 2=Ativo (default '2').
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const cod = String(r.A1_COD || '').trim();
  const loja = String(r.A1_LOJA || '').trim().padStart(2, '0');
  const blql = String(r.A1_MSBLQL || '').trim(); // 1=inativo, 2=ativo
  out.push({
    json: {
      a1_codcli_raw: cod + loja,
      a1_nome: r.A1_NOME || null,
      a1_nreduz: r.A1_NREDUZ || null,
      a1_pessoa: r.A1_PESSOA || null,
      a1_cgc: r.A1_CGC || null,
      a1_pricom: (r.A1_PRICOM && r.A1_PRICOM.toString().trim().length === 8) 
  ? `${r.A1_PRICOM.substring(0, 4)}-${r.A1_PRICOM.substring(4, 6)}-${r.A1_PRICOM.substring(6, 8)}` 
  : null,
      a1_ultcom: (r.A1_ULTCOM && r.A1_ULTCOM.toString().trim().length === 8) 
  ? `${r.A1_ULTCOM.substring(0, 4)}-${r.A1_ULTCOM.substring(4, 6)}-${r.A1_ULTCOM.substring(6, 8)}` 
  : null,
      a1_vend: r.A1_VEND || null,
      a1_risco: r.A1_RISCO || null,
      a1_lc: r.A1_LC != null ? Number(r.A1_LC) : null,
      a1_sativ1: r.A1_SATIV1 || null,
      a1_end: r.A1_END || null,
      a1_cep: r.A1_CEP || null,
      a1_bairro: r.A1_BAIRRO || null,
      a1_est: r.A1_EST || null,
      a1_cod_mun: r.A1_COD_MUN || null,
      a1_mun: r.A1_MUN || null,
      a1_ativo_raw: blql === '2' ? '1' : '0',
      a1_inativo_raw: blql === '1' ? '1' : '0',
      cliente_codigo: cod + loja,
      a1_cod: r.A1_COD || null,
      a1_loja: r.A1_LOJA || null,
      a1_ativo: blql === '2' ? true : false,
      a1_inativo: blql === '1' ? true : false
    }
  });
}
return out;

for (const item of $input.all()) {
  for (const key in item.json) {
    // Se o valor for uma string vazia ou apenas espaços, transforma em null
    if (typeof item.json[key] === 'string' && item.json[key].trim() === '') {
      item.json[key] = null;
    }
  }
}
return $input.all();

// Monta INSERT ... ON CONFLICT (upsert) em batches de 500 linhas para
// castor_src_sa1010, no lugar de TRUNCATE+INSERT (lock exclusivo lento).
// Requer UNIQUE INDEX em a1_codcli_raw (migration 048_sa1010_upsert_key.sql).
const rows = $input.all();

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  if (typeof v === 'number') return isNaN(v) ? 'NULL' : String(v);
  const s = String(v).trim();
  if (s === '') return 'NULL';
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return `'${s}'`;
  return `'${s.replace(/'/g, "''")}'`;
}

const cols = [
  'a1_codcli_raw', 'a1_nome', 'a1_nreduz', 'a1_pessoa', 'a1_cgc',
  'a1_pricom', 'a1_ultcom', 'a1_vend', 'a1_risco', 'a1_lc', 'a1_sativ1',
  'a1_end', 'a1_cep', 'a1_bairro', 'a1_est', 'a1_cod_mun', 'a1_mun',
  'a1_ativo_raw', 'a1_inativo_raw', 'cliente_codigo', 'a1_cod', 'a1_loja',
  'a1_ativo', 'a1_inativo'
];

const batchSize = 500;
const batches = [];
for (let i = 0; i < rows.length; i += batchSize) {
  const chunk = rows.slice(i, i + batchSize);
  const values = chunk.map(item => {
    const r = item.json;
    return `(${cols.map(c => esc(r[c])).join(',')},NOW())`;
  }).join(',\n');
  const updateSet = cols
    .filter(c => c !== 'a1_codcli_raw')
    .map(c => `${c}=EXCLUDED.${c}`)
    .concat('ingested_at=NOW()')
    .join(',');
  batches.push({
    json: {
      sql: `INSERT INTO castor_src_sa1010 (${cols.join(',')},ingested_at) VALUES ${values} ON CONFLICT (a1_codcli_raw) DO UPDATE SET ${updateSet}`,
      rowCount: chunk.length
    }
  });
}
if (batches.length === 0) batches.push({ json: { sql: 'SELECT 1', rowCount: 0 } });
return batches;
